scripts.kick-host.probe:
{
  "schema": 1,
  "timeout_ms": 360000,
  "steps": [
    {
      "op": "wait",
      "editing": true
    },
    {
      "op": "assert_relay"
    },
    {
      "op": "editor_pick",
      "input_player": 0
    },
    {
      "op": "editor_move",
      "input_player": 0,
      "x_fraction": 0.35
    },
    {
      "op": "wait",
      "renders": 5,
      "elapsed_ms": 1000
    },
    {
      "op": "menu",
      "command": "video_mark valid-preview-host"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200,
      "scope": "menu"
    },
    {
      "op": "screenshot_pair",
      "name": "valid-preview-host",
      "scope": "menu"
    },
    {
      "op": "assert_editor",
      "input_player": 0,
      "screen_text_contains": "Valid spot - click to INSTALL your brain"
    },
    {
      "op": "assert_control",
      "control": "LabelNetMatchStatus",
      "text_contains": "0 of 2",
      "fits": true,
      "inside": "BoxNetMatchStatus"
    },
    {
      "op": "game_mouse",
      "button": "left",
      "down": true
    },
    {
      "op": "wait",
      "renders": 3,
      "sim_advanced": 2
    },
    {
      "op": "game_mouse",
      "button": "left",
      "down": false
    },
    {
      "op": "wait",
      "renders": 3
    },
    {
      "op": "wait",
      "setup_ready": 1
    },
    {
      "op": "menu",
      "command": "video_mark placed-host"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200,
      "scope": "menu"
    },
    {
      "op": "screenshot_pair",
      "name": "placed-host",
      "scope": "menu"
    },
    {
      "op": "assert_editor",
      "input_player": 0,
      "equals": {
        "ready": true,
        "submitted": true
      }
    },
    {
      "op": "assert_control",
      "control": "LabelNetMatchStatus",
      "text_contains": "1 of 2",
      "fits": true,
      "inside": "BoxNetMatchStatus"
    },
    {
      "op": "key_down",
      "key": "Return"
    },
    {
      "op": "wait",
      "renders": 3,
      "sim_advanced": 2
    },
    {
      "op": "key_up",
      "key": "Return"
    },
    {
      "op": "wait",
      "renders": 3
    },
    {
      "op": "wait",
      "editing": false,
      "paused": false
    },
    {
      "op": "assert_scene",
      "input_player": 0,
      "equals": {
        "alive": true,
        "brain_count": 2
      }
    },
    {
      "op": "menu",
      "command": "video_mark playing-host"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200,
      "scope": "menu"
    },
    {
      "op": "screenshot_pair",
      "name": "playing-host",
      "scope": "menu"
    },
    {
      "op": "key_down",
      "key": "F6"
    },
    {
      "op": "wait",
      "renders": 3,
      "sim_advanced": 2
    },
    {
      "op": "key_up",
      "key": "F6"
    },
    {
      "op": "wait",
      "renders": 3
    },
    {
      "op": "wait",
      "panel_open": true
    },
    {
      "op": "menu",
      "command": "activate NetworkSeatRemove@Joiner"
    },
    {
      "op": "menu",
      "command": "video_mark confirm-kick"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200,
      "scope": "menu"
    },
    {
      "op": "screenshot_pair",
      "name": "confirm-kick",
      "scope": "menu"
    },
    {
      "op": "assert_control",
      "control": "NetworkSeatRemove@Joiner",
      "text_contains": "Confirm: remove Joiner",
      "fits": true
    },
    {
      "op": "menu",
      "command": "activate NetworkSeatRemove@Joiner"
    },
    {
      "op": "wait",
      "elapsed_ms": 25000
    },
    {
      "op": "assert_scene",
      "input_player": 0,
      "equals": {
        "alive": true
      }
    },
    {
      "op": "finish"
    }
  ],
  "activate_phase": "Running",
  "sim_clock": "lockstep"
}

